<template><section class="workspace-page focus-page"><PageHeader title="专注眼前这一小步。" description="留一段安静的时间，也可以带着自己的讲义一起学。" eyebrow="专注学习"/><div v-if="store.error||error" class="m-error" role="alert">{{ error||store.error }}<button class="m-btn m-btn--ghost m-btn--sm" @click="store.refresh">重新读取</button></div><div class="focus-page-layout"><DashboardWidget title="把这一段时间，留给理解"><div class="focus-context"><label class="m-field"><span>关联目标</span><select v-model="goalId" :disabled="!!current" class="m-input"><option value="">独立专注，不关联目标</option><option v-for="goal in store.workspace?.goals||[]" :key="goal.id" :value="goal.id">{{ goal.title }}</option></select></label><label class="m-field"><span>关联知识点（本机）</span><select v-model="topicId" :disabled="!!current" class="m-input"><option value="">不关联具体知识点</option><optgroup v-for="phase in store.path?.phases||[]" :key="phase.id" :label="phase.name"><option v-for="topic in phase.topics" :key="topic.id" :value="topic.id">{{ topic.name }}</option></optgroup></select></label><p v-if="linkedTask" class="workspace-caption">关联任务：{{ linkedTask.title }}。计时达到 80% 后，可由你确认任务完成。</p></div><FocusTimer v-model:minutes="minutes" :seconds="remaining" :status="current?.status" :busy="busy" @action="action"/><p v-if="store.storageError" class="m-error" role="alert">{{ store.storageError }}</p><div v-if="summary" class="focus-summary" role="status"><h3>这次专注，已经留下记录。</h3><p>实际计时 {{ Math.floor(summary.seconds/60) }} 分 {{ summary.seconds%60 }} 秒；{{ summary.reward?'已按有效专注发放星粮。':'未达到奖励条件，不发放星粮。' }}</p><button v-if="linkedTask&&!linkedTask.done&&summary.reward" class="m-btn m-btn--ghost m-btn--sm" :disabled="busy" @click="completeLinkedTask">确认关联任务已完成</button><RouterLink to="/pet" class="workspace-text-action">去看看小伙伴 →</RouterLink></div></DashboardWidget><div><DashboardWidget title="选择这次的学习方式"><div class="focus-modes"><button :aria-pressed="mode==='independent'" @click="mode='independent'">独立专注</button><button :aria-pressed="mode==='materials'" @click="mode='materials'">知识库伴学</button></div><template v-if="mode==='independent'"><div class="focus-companion"><AIPetAvatar :kind="store.local.pet" :stage="store.pet.stage"/><p>我在这里，陪你把这一点想明白。</p></div><p class="workspace-caption">你可以自行阅读、做题或复述。离开页面时可保留进度，不会因中断扣除奖励。</p></template><template v-else><label class="m-field"><span>选择已导入的资料</span><select v-model="materialId" class="m-input"><option value="">请选择资料</option><option v-for="material in store.workspace?.materials.filter(m=>m.status==='ready')||[]" :key="material.id" :value="material.id">{{ material.title }}</option></select></label><div v-if="material" class="focus-reading"><h3>{{ material.title }}</h3><p v-for="section in material.sections.slice(0,6)" :key="section.id"><small>{{ section.page?`第 ${section.page} 页 · `:'' }}段落 {{ section.paragraph }}</small>{{ section.text }}</p></div><p v-else class="workspace-caption">当前没有选中的资料。请先从知识库导入讲义或笔记。</p><div class="workspace-actions"><RouterLink :to="{path:'/library',query:{...(materialId?{material:materialId}:{})}}" class="m-btn m-btn--ghost m-btn--sm">资料原文与来源问答</RouterLink><RouterLink to="/tutor" class="m-btn m-btn--ghost m-btn--sm">向 AI 导师提问</RouterLink></div></template></DashboardWidget><DashboardWidget class="focus-records" title="最近的专注记录"><p v-if="!completed.length" class="workspace-caption">尚无已结束计时。开始与结束后，会保留真实记录。</p><div v-for="focus in completed.slice(0,5)" :key="focus.id" class="focus-history-row"><span>{{ dateLabel(focus.finishedAt||focus.startedAt) }}</span><b>{{ Math.floor(focus.accumulatedSeconds/60) }} 分 {{ focus.accumulatedSeconds%60 }} 秒</b></div></DashboardWidget></div></div><AppDialog v-model="resetOpen" title="重置这一段计时？" :persistent="busy"><p>当前计时会结束并保存真实经过的时间。重置只让下一段从零开始，不会撤销已有学习记录。</p><template #footer><button class="m-btn m-btn--ghost" @click="resetOpen=false">继续这一段</button><button class="m-btn m-btn--primary" :disabled="busy" @click="resetTimer">结束并重置</button></template></AppDialog><AppDialog :model-value="exitOpen" title="要离开专注页吗？" :persistent="busy" @update:model-value="cancelExit"><p>可以暂停并保留进度，回来再继续；也可以结束并保存这一段。</p><template #footer><button class="m-btn m-btn--ghost" @click="cancelExit">继续专注</button><button class="m-btn m-btn--ghost" :disabled="busy" @click="leave(false)">暂停并保留进度</button><button class="m-btn m-btn--primary" :disabled="busy" @click="leave(true)">结束并离开</button></template></AppDialog></section></template>
<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import { onBeforeRouteLeave,useRoute } from 'vue-router'
import { useLearningWorkspace } from '@/mobile/stores/learning-workspace'
import { activeGoal,changeWorkspace,dateLabel,type Focus } from '@/mobile/data/workspace'
import PageHeader from '@/mobile/components/PageHeader.vue'
import FocusTimer from '@/mobile/components/FocusTimer.vue'
import DashboardWidget from '@/mobile/components/DashboardWidget.vue'
import AIPetAvatar from '@/mobile/components/AIPetAvatar.vue'
import AppDialog from '@/mobile/components/AppDialog.vue'
const store=useLearningWorkspace(),route=useRoute(),minutes=ref(25),tick=ref(Date.now()),busy=ref(false),error=ref(''),goalId=ref(''),materialId=ref(''),topicId=ref(''),mode=ref('independent'),resetOpen=ref(false),exitOpen=ref(false),summary=ref<{seconds:number;reward:boolean}|null>(null)
const current=computed(()=>store.workspace?.focus.find(f=>f.status==='running'||f.status==='paused')),completed=computed(()=>store.workspace?.focus.filter(f=>f.status==='completed')||[]),material=computed(()=>store.workspace?.materials.find(m=>m.id===materialId.value))
const taskId=ref(typeof route.query.task==='string'?route.query.task:''),linkedTask=computed(()=>store.taskItems.find(t=>t.id===(taskId.value||store.local.focusLinks[current.value?.id||'']?.taskId)))
const elapsed=computed(()=>current.value?Math.min(current.value.minutes*60,current.value.accumulatedSeconds+(current.value.status==='running'?Math.max(0,Math.floor((tick.value-Date.parse(current.value.resumedAt))/1000)):0)):0),remaining=computed(()=>Math.max(0,(current.value?.minutes||minutes.value)*60-elapsed.value))
let timer:ReturnType<typeof setInterval>|undefined,exitResolve:((value:boolean)=>void)|undefined
onMounted(async()=>{await store.refresh();goalId.value=current.value?.goalId||((typeof route.query.goal==='string'&&store.workspace?.goals.some(g=>g.id===route.query.goal))?route.query.goal:activeGoal(store.workspace)?.id)||'';materialId.value=typeof route.query.material==='string'&&store.workspace?.materials.some(m=>m.id===route.query.material)?route.query.material:'';topicId.value=typeof route.query.topic==='string'&&store.path?.phases.some(p=>p.topics.some(t=>t.id===route.query.topic))?route.query.topic:'';const restored=store.local.focusLinks[current.value?.id||''];if(!topicId.value&&restored?.topicId)topicId.value=restored.topicId;if(!taskId.value&&restored?.taskId)taskId.value=restored.taskId;if(!materialId.value&&restored?.materialId)materialId.value=restored.materialId;if(materialId.value||route.query.mode==='materials')mode.value='materials';timer=setInterval(()=>{tick.value=Date.now()},1000)})
watch(remaining,value=>{if(value===0&&current.value?.status==='running'&&!busy.value)void action('finish')})
onBeforeUnmount(()=>{if(timer)clearInterval(timer);exitResolve?.(false)})
onBeforeRouteLeave(()=>{if(!current.value)return true;exitOpen.value=true;return new Promise<boolean>(resolve=>{exitResolve=resolve})})
async function send(action:string){const id=current.value?.id;const response=await changeWorkspace<{result:Focus}>('focus',{action,id,minutes:minutes.value,goalId:goalId.value||undefined});if(action==='start'){store.local.focusLinks[response.result.id]={taskId:taskId.value||undefined,goalId:response.result.goalId||undefined,materialId:materialId.value||undefined,topicId:topicId.value||undefined};store.persist()}await store.refresh();if(action==='finish'){const focus=response.result;summary.value={seconds:focus.accumulatedSeconds,reward:focus.accumulatedSeconds>=60&&focus.accumulatedSeconds>=focus.minutes*60*.8}}return response.result}
async function action(value:string){if(value==='reset'){resetOpen.value=true;return}busy.value=true;error.value='';try{await send(value)}catch(e){error.value=e instanceof Error?e.message:'计时保存失败，可重试'}finally{busy.value=false}}
async function resetTimer(){busy.value=true;try{await send('finish');minutes.value=25;resetOpen.value=false}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
function cancelExit(){exitOpen.value=false;exitResolve?.(false);exitResolve=undefined}
async function leave(finish:boolean){busy.value=true;try{if(finish)await send('finish');else if(current.value?.status==='running')await send('pause');exitOpen.value=false;exitResolve?.(true);exitResolve=undefined}catch(e){error.value=e instanceof Error?e.message:'保存失败，请重试'}finally{busy.value=false}}
async function completeLinkedTask(){const task=linkedTask.value;if(!task)return;busy.value=true;try{await changeWorkspace('checklist',{taskId:task.taskId,id:task.id,done:true});await store.refresh()}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
</script>
<style scoped>.focus-page-layout{display:grid;gap:20px}.focus-context{margin-bottom:16px}.focus-summary{padding:18px;background:var(--m-success-soft);border:1px solid var(--m-success);border-radius:16px;margin-top:18px}.focus-summary h3{font-size:17px;margin:0 0 12px}.focus-summary p{font-size:14px;line-height:1.8;color:var(--m-text-dim)}.focus-modes{display:flex;gap:8px;margin-bottom:18px}.focus-modes button{flex:1;border:1px solid var(--m-border);border-radius:12px;background:var(--m-bg);color:var(--m-text-dim);min-height:44px;font:inherit;font-size:14px}.focus-modes button[aria-pressed=true]{color:var(--m-primary);border-color:var(--m-primary-border);background:var(--m-primary-soft)}.focus-companion{text-align:center}.focus-companion .ai-pet-avatar{width:165px;margin:auto}.focus-companion p{font-size:14px;color:var(--m-text-dim)}.focus-reading{max-height:340px;overflow:auto;margin-top:20px}.focus-reading h3{font-size:18px}.focus-reading p{font-size:15px;line-height:1.9;white-space:pre-wrap}.focus-reading small{display:block;font-size:12px;color:var(--m-primary)}.focus-records{margin-top:20px}.focus-history-row{display:flex;justify-content:space-between;gap:12px;padding:13px 0;border-bottom:1px solid var(--m-border);font-size:13px;color:var(--m-text-dim)}@media(min-width:1050px){.focus-page-layout{grid-template-columns:1.05fr 1fr;align-items:start}}
</style>
